const response = await fetch('https://api.aimlapi.com/v1/messages', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer <YOUR_AIMLAPI_KEY>',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
  "model": "tencent/hy4-flash",
  "messages": [
    "<message>"
  ]
}),
});

console.log(await response.json());

import requests

response = requests.post(
    "https://api.aimlapi.com/v1/messages",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'tencent/hy4-flash', 'messages': ['<message>']},
)

print(response.json())
